document.addEventListener('DOMContentLoaded', () => {
    const viewer = document.querySelector<HTMLElement>('.animations-viewer');
    if (!viewer) return;

    const backdrop = document.createElement('div');
    backdrop.className = 'fullscreen-backdrop';
    viewer.appendChild(backdrop);

    let activeFrame: HTMLElement | null = null;
    let activeFocus: HTMLElement | null = null;
    let activeTrigger: HTMLButtonElement | null = null;

    function minimizeMedia(): void {
        if (!activeFrame) return;

        activeFrame.classList.remove('is-fullscreen');
        activeFrame.querySelector('.minimize-btn')?.remove();

        // Release the space reserved while the frame was lifted out of the layout
        if (activeFocus) activeFocus.style.minHeight = '';

        backdrop.classList.remove('active');
        viewer?.classList.remove('has-fullscreen');
        document.body.style.overflow = '';

        activeTrigger?.focus();

        activeFrame = null;
        activeFocus = null;
        activeTrigger = null;
    }

    function expandMedia(
        frame: HTMLElement,
        focusContainer: HTMLElement,
        trigger: HTMLButtonElement
    ): void {
        if (activeFrame) minimizeMedia();

        activeFrame = frame;
        activeFocus = focusContainer;
        activeTrigger = trigger;

        // Keep the page from jumping when the frame becomes position: fixed
        focusContainer.style.minHeight = `${focusContainer.offsetHeight}px`;

        frame.classList.add('is-fullscreen');

        // Appended inside the frame; CSS anchors it below the enlarged panel
        const minimizeButton = document.createElement('button');
        minimizeButton.className = 'minimize-btn btn';
        minimizeButton.type = 'button';
        minimizeButton.textContent = '− Minimize';
        minimizeButton.setAttribute('aria-label', 'Exit fullscreen');
        minimizeButton.addEventListener('click', minimizeMedia);
        frame.appendChild(minimizeButton);

        backdrop.classList.add('active');
        viewer?.classList.add('has-fullscreen');
        document.body.style.overflow = 'hidden';

        minimizeButton.focus();
    }

    viewer.querySelectorAll<HTMLButtonElement>('.fullscreen-btn').forEach((button) => {
        button.addEventListener('click', () => {
            const focusContainer = button.closest<HTMLElement>('.media-focus');
            const frame = focusContainer?.querySelector<HTMLElement>('.media-frame');

            if (!focusContainer || !frame) return;
            expandMedia(frame, focusContainer, button);
        });
    });

    backdrop.addEventListener('click', minimizeMedia);

    document.addEventListener('keydown', (event: KeyboardEvent) => {
        if (event.key === 'Escape') minimizeMedia();
    });
});